using System;
using System.Collections.Generic;
using System.Linq;

namespace PetStar.Rules
{
    /// <summary>Source of uniform integers in [0, maxExclusive). Server uses a CSPRNG implementation.</summary>
    public interface IRandomSource
    {
        int Next(int maxExclusive);
    }

    /// <summary>Deterministic PRNG (SplitMix64) for battle replay. Seed is generated by the server CSPRNG and
    /// kept secret until the battle ends so clients cannot predict crits/status procs.</summary>
    public sealed class SeededRandom : IRandomSource
    {
        private ulong _state;
        public SeededRandom(ulong seed) { _state = seed; }
        public ulong State => _state;

        public ulong NextULong()
        {
            ulong z = (_state += 0x9E3779B97F4A7C15UL);
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            return z ^ (z >> 31);
        }

        public int Next(int maxExclusive)
        {
            if (maxExclusive <= 0) throw new ArgumentOutOfRangeException(nameof(maxExclusive));
            // rejection sampling to avoid modulo bias
            ulong bound = (ulong)maxExclusive;
            ulong limit = ulong.MaxValue - (ulong.MaxValue % bound);
            ulong r;
            do { r = NextULong(); } while (r >= limit);
            return (int)(r % bound);
        }

        public bool Chance(double p) => p >= 1.0 || (p > 0 && Next(1_000_000) < (int)(p * 1_000_000));
    }

    /// <summary>Integer weight table in parts-per-million.</summary>
    public static class WeightedTable
    {
        public const int Total = 1_000_000;

        public static string Roll(IReadOnlyDictionary<string, int> table, IRandomSource rng, IList<string> order)
        {
            int sum = table.Values.Sum();
            if (sum <= 0) throw new InvalidOperationException("Empty weight table");
            int r = rng.Next(sum);
            int acc = 0;
            // iterate in a fixed, documented order so results are reproducible for a given random value
            foreach (var key in order)
            {
                if (!table.TryGetValue(key, out var w) || w <= 0) continue;
                acc += w;
                if (r < acc) return key;
            }
            throw new InvalidOperationException("Weight table order is missing keys");
        }
    }
}
